#[derive(Clone)]
struct LogSettings { level: Arc<Mutex<u8>> }   // clones share the state

impl LogSettings {
    fn set_level(&self, v: u8) { *self.level.lock().unwrap() = v; }
    fn level(&self) -> u8     { *self.level.lock().unwrap() }
}

let settings = LogSettings { level: Arc::new(Mutex::new(1)) };
let a = settings.clone();                       // ordinary value-semantics handle
a.set_level(3);
assert_eq!(settings.level(), 3);
